import re
from typing import Any, Dict, List, Tuple, Union

# ----------------------------------------------------------------------
# Helpers provided by the framework (assumed to be available in the sandbox)
# ----------------------------------------------------------------------
# def node_by_title(doc: Dict, title: str) -> Dict
# def node_by_id(doc: Dict, node_id: str) -> Dict
# def children(doc: Dict, node: Dict) -> List[Dict]
# def scope_nodes(doc: Dict, scope: str) -> List[Dict]
# def table_rows(node: Dict) -> List[Tuple[int, Dict[str, str]]]
# ----------------------------------------------------------------------


# ----------------------------------------------------------------------
# Utilities
# ----------------------------------------------------------------------
def _find_node_by_title(doc: Dict, title: str) -> Union[Dict[str, Any], None]:
    """Return first node with exactly the given title."""
    for n in doc.get("nodes", []):
        if n.get("title") == title:
            return n
    return None


def _parse_int(s: str) -> Union[int, None]:
    try:
        return int(s)
    except Exception:
        return None


def _parse_float(s: str) -> Union[float, None]:
    try:
        return float(s)
    except Exception:
        return None


def _src(node_id: str, row_index: int, cols: List[str]) -> List[List[Any]]:
    """Return source location spec for the specified cells."""
    return [[node_id, row_index, cols]]


# ----------------------------------------------------------------------
# API functions
# ----------------------------------------------------------------------
def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    """Return all product entities present in the supplied scope."""
    node = _find_node_by_title(doc, f"{scope}: Products")
    if not node:
        return []

    ent = []
    for _, row in table_rows(node):
        pid = row.get("product")
        if pid:
            ent.append({"id": pid, "description": pid})
    return ent


def recorded_end(doc: Dict[str, Any], scope: str) -> Union[float, None]:
    """Return the last day number recorded in the period."""
    node = _find_node_by_title(doc, f"{scope}: Daily ledger")
    if not node:
        return None
    max_day = None
    for _, row in table_rows(node):
        d = _parse_int(row.get("day", ""))
        if d is not None:
            max_day = d if max_day is None else max(max_day, d)
    return float(max_day) if max_day is not None else None


def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """All external inputs to the process."""
    res: List[Dict[str, Any]] = []

    # Opening stock (at time None)
    prod_node = _find_node_by_title(doc, f"{scope}: Products")
    if prod_node:
        for idx, row in table_rows(prod_node):
            pid = row.get("product")
            opening = _parse_int(row.get("opening stock", ""))
            if pid and opening is not None:
                res.append(
                    {
                        "id": f"{pid}_opening_stock",
                        "time": None,
                        "kind": "opening_stock",
                        "entities": [pid],
                        "fields": {"stock": opening},
                        "src": _src(prod_node["node_id"], idx, ["product", "opening stock"]),
                    }
                )

    # Daily production and orders
    ledger_node = _find_node_by_title(doc, f"{scope}: Daily ledger")
    if ledger_node:
        for idx, row in table_rows(ledger_node):
            pid = row.get("product")
            day = _parse_int(row.get("day", ""))
            if not (pid and day is not None):
                continue

            produced = _parse_int(row.get("produced", ""))
            if produced is not None:
                res.append(
                    {
                        "id": f"{pid}_prod_{day}",
                        "time": float(day),
                        "kind": "production",
                        "entities": [pid],
                        "fields": {"produced": produced},
                        "src": _src(
                            ledger_node["node_id"],
                            idx,
                            ["day", "product", "produced"],
                        ),
                    }
                )

            ordered = _parse_int(row.get("ordered", ""))
            if ordered is not None:
                res.append(
                    {
                        "id": f"{pid}_order_{day}",
                        "time": float(day),
                        "kind": "order_placed",
                        "entities": [pid],
                        "fields": {"ordered": ordered},
                        "src": _src(
                            ledger_node["node_id"],
                            idx,
                            ["day", "product", "ordered"],
                        ),
                    }
                )

    # Order book (future production / orders)
    for order_book_node in filter(
        lambda n: n.get("kind") == "table" and n.get("title", "").startswith(
            f"{scope}: Order book: Orders received and production planned for days"
        ),
        doc.get("nodes", []),
    ):
        for idx, row in table_rows(order_book_node):
            pid = row.get("product")
            day = _parse_int(row.get("day", ""))
            if not (pid and day is not None):
                continue

            planned_prod = _parse_int(row.get("planned production", ""))
            if planned_prod is not None:
                res.append(
                    {
                        "id": f"{pid}_future_prod_{day}",
                        "time": float(day),
                        "kind": "future_production",
                        "entities": [pid],
                        "fields": {"produced": planned_prod},
                        "src": _src(
                            order_book_node["node_id"],
                            idx,
                            ["day", "product", "planned production"],
                        ),
                    }
                )

            ordered = _parse_int(row.get("ordered", ""))
            if ordered is not None:
                res.append(
                    {
                        "id": f"{pid}_future_order_{day}",
                        "time": float(day),
                        "kind": "future_order",
                        "entities": [pid],
                        "fields": {"ordered": ordered},
                        "src": _src(
                            order_book_node["node_id"],
                            idx,
                            ["day", "product", "ordered"],
                        ),
                    }
                )

    return res


def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """All recorded outcomes of the process."""
    res: List[Dict[str, Any]] = []

    # From Daily ledger
    ledger_node = _find_node_by_title(doc, f"{scope}: Daily ledger")
    if ledger_node:
        for idx, row in table_rows(ledger_node):
            pid = row.get("product")
            day = _parse_int(row.get("day", ""))
            if pid and day is not None:
                time = float(day)
                # shipped
                shipped = _parse_int(row.get("shipped", ""))
                if shipped is not None:
                    res.append(
                        {
                            "time": time,
                            "kind": "shipped",
                            "entities": [pid],
                            "value": shipped,
                            "src": _src(
                                ledger_node["node_id"],
                                idx,
                                ["day", "product", "shipped"],
                            ),
                        }
                    )
                # backordered
                back = _parse_int(row.get("backordered", ""))
                if back is not None:
                    res.append(
                        {
                            "time": time,
                            "kind": "backordered",
                            "entities": [pid],
                            "value": back,
                            "src": _src(
                                ledger_node["node_id"],
                                idx,
                                ["day", "product", "backordered"],
                            ),
                        }
                    )
                # stock
                stock = _parse_int(row.get("stock", ""))
                if stock is not None:
                    res.append(
                        {
                            "time": time,
                            "kind": "stock",
                            "entities": [pid],
                            "value": stock,
                            "src": _src(
                                ledger_node["node_id"],
                                idx,
                                ["day", "product", "stock"],
                            ),
                        }
                    )

    # From Events list
    events_node = _find_node_by_title(doc, f"{scope}: Events")
    if events_node and events_node.get("kind") == "list":
        lines = events_node.get("lines", [])
        for idx, line in enumerate(lines):
            # runs out of stock
            m = re.search(r"Day\s+(\d+).*runs out of stock.*\((\d+)\s+units backordered\)", line, re.I)
            if m:
                day = float(m.group(1))
                units = int(m.group(2))
                # try to capture product if present
                prod = None
                prod_match = re.search(r":\s*([A-Z0-9]+)\s+runs out of stock", line)
                if prod_match:
                    prod = prod_match.group(1)
                res.append(
                    {
                        "time": day,
                        "kind": "runs_out_of_stock",
                        "entities": [prod] if prod else [],
                        "value": units,
                        "src": [[events_node["node_id"], idx]],
                    }
                )
                continue

            # capacity reached
            m = re.search(r"Day\s+(\d+).*capacity reached", line, re.I)
            if m:
                day = float(m.group(1))
                res.append(
                    {
                        "time": day,
                        "kind": "capacity_reached",
                        "entities": [],
                        "value": None,
                        "src": [[events_node["node_id"], idx]],
                    }
                )
                continue

            # order fully backordered
            m = re.search(
                r"order for (\S+) placed on day (\d+) fully backordered.*\((\d+)\s+units, none shipped\)",
                line,
                re.I,
            )
            if m:
                pid = m.group(1)
                day = float(m.group(2))
                units = int(m.group(3))
                res.append(
                    {
                        "time": day,
                        "kind": "order_fully_backordered",
                        "entities": [pid],
                        "value": units,
                        "src": [[events_node["node_id"], idx]],
                    }
                )
                continue

            # backlog cleared
            m = re.search(r"backlog cleared for (\S+)", line, re.I)
            if m:
                pid = m.group(1)
                # day is not directly in the string; infer from preceding "Day X"
                m_day = re.search(r"Day\s+(\d+)", line)
                day = float(m_day.group(1)) if m_day else None
                res.append(
                    {
                        "time": day,
                        "kind": "backlog_cleared",
                        "entities": [pid],
                        "value": None,
                        "src": [[events_node["node_id"], idx]],
                    }
                )
                continue

    return res


def params(doc: Dict[str, Any], scope: str) -> Dict[str, Union[int, float]]:
    """Return constants declared in the scope."""
    out: Dict[str, Union[int, float]] = {}

    # Dispatch capacity
    scope_node = _find_node_by_title(doc, scope)
    if scope_node and scope_node.get("kind") == "text":
        txt = scope_node.get("text", "")
        m = re.search(r"Daily dispatch capacity:\s+([\d,]+)\s+kg", txt)
        if m:
            cap = int(m.group(1).replace(",", ""))
            cap = int(round(cap / 50.0) * 50)  # nearest 50 kg
            out["dispatch_capacity_kg"] = cap

    # Product weights
    prod_node = _find_node_by_title(doc, f"{scope}: Products")
    if prod_node:
        for _, row in table_rows(prod_node):
            pid = row.get("product")
            kg_str = row.get("kg per unit")
            if pid and kg_str:
                try:
                    out[f"weight_{pid}_kg"] = float(kg_str)
                except Exception:
                    continue
    return out


# ---- step 2: forward model ----
def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Forward model of the plant dispatch process.

    Parameters
    ----------
    doc : dict
        Full document (used only to obtain product list via entities()).
    scope : str
        Title of the plant‑period scope.
    inputs : list[dict]
        Input records produced by inputs().
    params : dict
        Constants from params().
    start : float | None
        Simulation start time. Defaults to the first day of the period.
    horizon : float | None
        Simulation end time. Defaults to the recorded end of the scope
        (or ``start`` if none).

    Returns
    -------
    list[dict]
        Outcome records in the same form as produced by outcomes()
        – each record has keys *time*, *kind*, *entities*, and *value*.
    """
    # ----------------------------------------------------------------------
    #  Parse inputs into maps
    # ----------------------------------------------------------------------
    stock_start = {}
    prod_map = {}
    order_map = {}
    for inp in inputs:
        pid = inp["entities"][0]
        kind = inp["kind"]
        if kind == "opening_stock":
            stock_start[pid] = inp["fields"]["stock"]
        elif kind in ("production", "future_production"):
            prod_map[(pid, int(inp["time"]))] = int(inp["fields"]["produced"])
        elif kind in ("order_placed", "future_order"):
            order_map[(pid, int(inp["time"]))] = int(inp["fields"]["ordered"])

    # ----------------------------------------------------------------------
    #  Get all product IDs in the scope
    # ----------------------------------------------------------------------
    all_pids = {e["id"] for e in entities(doc, scope)}
    for inp in inputs:
        all_pids.add(inp["entities"][0])

    # ----------------------------------------------------------------------
    #  Simulation time limits
    # ----------------------------------------------------------------------
    start = 1.0 if start is None or start < 1 else float(start)
    if horizon is None:
        rec_end = recorded_end(doc, scope)
        horizon = rec_end if rec_end is not None else start
    horizon = int(horizon)

    # ----------------------------------------------------------------------
    #  Weight per unit and capacity
    # ----------------------------------------------------------------------
    weight = {pid: params.get(f"weight_{pid}_kg", 1.0) for pid in all_pids}
    capacity_kg = params.get("dispatch_capacity_kg", 0)

    # ----------------------------------------------------------------------
    #  Initial state
    # ----------------------------------------------------------------------
    stock = {pid: stock_start.get(pid, 0) for pid in all_pids}
    order_queue = []

    def _prod_on(pid, day): return prod_map.get((pid, day), 0)
    def _order_on(pid, day): return order_map.get((pid, day), 0)

    outcomes = []

    # ----------------------------------------------------------------------
    #  Main simulation loop
    # ----------------------------------------------------------------------
    for day in range(1, horizon + 1):
        # 1. Production arrives
        for pid in all_pids:
            stock[pid] += _prod_on(pid, day)

        # 2. New orders join the queue
        for pid in all_pids:
            qty = _order_on(pid, day)
            if qty > 0:
                order_queue.append({"pid": pid, "day": day, "remaining": qty})

        # 3. Dispatch – obey policy order
        order_queue.sort(key=lambda o: (o["day"], o["remaining"], o["pid"]))
        cap_left = capacity_kg
        shipped_today = {pid: 0 for pid in all_pids}
        for order in list(order_queue):
            if cap_left <= 0:
                break
            pid = order["pid"]
            # Whole units that can be shipped
            can_ship = int(min(order["remaining"], cap_left / weight[pid]))
            if can_ship <= 0:
                continue
            order["remaining"] -= can_ship
            cap_left -= can_ship * weight[pid]
            stock[pid] -= can_ship
            shipped_today[pid] += can_ship
            if order["remaining"] == 0:
                order_queue.remove(order)

        # 4. Backordered totals per product
        backorder = {pid: 0 for pid in all_pids}
        for order in order_queue:
            backorder[order["pid"]] += order["remaining"]

        # 5. Emit outcomes for days >= start
        if day >= start:
            for pid in sorted(all_pids):
                outcomes.append(
                    {"time": float(day), "kind": "shipped",
                     "entities": [pid], "value": shipped_today[pid]}
                )
                outcomes.append(
                    {"time": float(day), "kind": "backordered",
                     "entities": [pid], "value": backorder[pid]}
                )
                outcomes.append(
                    {"time": float(day), "kind": "stock",
                     "entities": [pid], "value": stock[pid]}
                )
    return outcomes

