import re
from typing import Any, Dict, List, Tuple, Union, Optional

# ------------- helpers -------------
# The following helpers are assumed to be available in the sandbox environment
# (they are provided by the surrounding framework).  They are listed here
# for reference, but their implementations are *not* required.

# def node_by_title(doc: Dict, title: str) -> Dict
# def node_by_id(doc: Dict, node_id: str) -> Dict
# def children(doc: Dict, node: Dict) -> List[Dict]
# def scope_nodes(doc: Dict, scope: str) -> List[Dict]
# def table_rows(node: Dict) -> List[Tuple[int, Dict[str, str]]]
# -----------------------------------

def _ensure_nodes(doc: Dict):
    """Return the nodes list for easier access."""
    return doc.get("nodes", [])


def _find_node_by_title(doc: Dict, title: str) -> Optional[Dict]:
    for n in _ensure_nodes(doc):
        if n.get("title") == title:
            return n
    return None


def _find_nodes_by_title_pattern(doc: Dict, pattern: str) -> List[Dict]:
    """Return all nodes whose title matches the pattern exactly."""
    import fnmatch
    results = []
    for n in _ensure_nodes(doc):
        if fnmatch.fnmatch(n.get("title", ""), pattern):
            results.append(n)
    return results


def _parse_capacity(text: str) -> Optional[int]:
    """Parse the capacity value from the period text."""
    m = re.search(r"Daily dispatch capacity:\s+([\d,]+)\s+kg", text)
    if m:
        return int(m.group(1).replace(",", ""))
    return None


def _parse_ledger_row(row: Dict[str, str], node_id: str, row_index: int) -> List[Dict[str, Any]]:
    """Return all outcome records for one ledger row."""
    day = row.get("day")
    try:
        day_float = float(day)
    except Exception:
        day_float = None
    out = []
    for field in ["shipped", "backordered", "stock"]:
        val_str = row.get(field, "")
        try:
            val = int(val_str)
        except Exception:
            val = None
        out.append(
            {
                "time": day_float,
                "kind": field,
                "entities": [],
                # we will populate entities later
                "value": val,
                "src": [[node_id, row_index, [field]]],
            }
        )
    return out


def _parse_events(lines: List[str], node_id: str) -> List[Dict[str, Any]]:
    """Parse events from the list of lines."""
    events = []

    run_out_pat = re.compile(
        r"Day\s+(\d+).* runs out of stock .* \((\d+) units backordered\)",
        re.IGNORECASE,
    )
    capacity_pat = re.compile(r"Day\s+(\d+).* capacity reached", re.IGNORECASE)
    backorder_pat = re.compile(
        r"Day\s+(\d+).*order for ([\w-]+?) placed on day \d+ fully backordered \((\d+) units, none shipped\)",
        re.IGNORECASE,
    )
    cleared_pat = re.compile(
        r"Day\s+(\d+).*backlog cleared for ([\w-]+)", re.IGNORECASE
    )

    for idx, line in enumerate(lines):
        m = run_out_pat.search(line)
        if m:
            events.append(
                {
                    "time": float(m.group(1)),
                    "kind": "runs_out_of_stock",
                    "entities": [],
                    "value": int(m.group(2)),
                    "src": [[node_id, idx]],
                }
            )
            continue
        m = capacity_pat.search(line)
        if m:
            events.append(
                {
                    "time": float(m.group(1)),
                    "kind": "capacity_reached",
                    "entities": [],
                    "value": None,
                    "src": [[node_id, idx]],
                }
            )
            continue
        m = backorder_pat.search(line)
        if m:
            events.append(
                {
                    "time": float(m.group(1)),
                    "kind": "order_fully_backordered",
                    "entities": [m.group(2)],
                    "value": int(m.group(3)),
                    "src": [[node_id, idx]],
                }
            )
            continue
        m = cleared_pat.search(line)
        if m:
            events.append(
                {
                    "time": float(m.group(1)),
                    "kind": "backlog_cleared",
                    "entities": [m.group(2)],
                    "value": None,
                    "src": [[node_id, idx]],
                }
            )
            continue
    return events


# ------------- required API -------------
def entities(doc: Dict, scope: str) -> List[Dict[str, str]]:
    """
    Every distinct entity the scope's records are about.
    For this document the sole entities are the product codes in the Products table.
    """
    prod_node = _find_node_by_title(doc, f"{scope}: Products")
    if not prod_node:
        return []

    ent_list = []
    for _, row in table_rows(prod_node):
        product = row.get("product")
        if product:
            ent_list.append({"id": product, "description": product})
    return ent_list


def recorded_end(doc: Dict, scope: str) -> Optional[float]:
    """
    The last time point covered by the scope's records.
    For this document it is the last day number present in the Daily ledger table.
    """
    ledger_node = _find_node_by_title(doc, f"{scope}: Daily ledger")
    if not ledger_node:
        return None

    max_day = None
    for _, row in table_rows(ledger_node):
        try:
            d = float(row.get("day", ""))
            if max_day is None or d > max_day:
                max_day = d
        except Exception:
            continue
    return max_day


def inputs(doc: Dict, scope: str) -> List[Dict[str, Any]]:
    """
    Everything that enters the process from outside and is not caused by it:
    - opening stock  (state at start of period)
    - daily production  (arrives each day)
    - daily orders  (customer requests)
    - planning tables  (future production and orders)
    """
    inputs_list = []

    # ----- opening stock -----
    prod_node = _find_node_by_title(doc, f"{scope}: Products")
    if prod_node:
        for _, row in table_rows(prod_node):
            product = row.get("product")
            opening = row.get("opening stock")
            try:
                opening_val = int(opening)
            except Exception:
                opening_val = None
            if product and opening_val is not None:
                inputs_list.append(
                    {
                        "id": f"{product}_open",
                        "time": None,
                        "kind": "opening_stock",
                        "entities": [product],
                        "fields": {"stock": opening_val},
                        "src": [[prod_node["node_id"], _, ["opening stock"]]],
                    }
                )

    # ----- daily production -----
    ledger_node = _find_node_by_title(doc, f"{scope}: Daily ledger")
    if ledger_node:
        for idx, row in table_rows(ledger_node):
            product = row.get("product")
            prod_val = row.get("produced")
            try:
                prod_int = int(prod_val)
            except Exception:
                prod_int = None
            if product and prod_int is not None:
                inputs_list.append(
                    {
                        "id": f"{product}_production_{row.get('day')}",
                        "time": float(row.get("day", "")),
                        "kind": "production",
                        "entities": [product],
                        "fields": {"produced": prod_int},
                        "src": [[ledger_node["node_id"], idx, ["produced"]]],
                    }
                )

            # ----- daily orders -----
            order_val = row.get("ordered")
            try:
                order_int = int(order_val)
            except Exception:
                order_int = None
            if product and order_int is not None and order_int > 0:
                inputs_list.append(
                    {
                        "id": f"{product}_order_{row.get('day')}",
                        "time": float(row.get("day", "")),
                        "kind": "order_placed",
                        "entities": [product],
                        "fields": {"ordered": order_int},
                        "src": [[ledger_node["node_id"], idx, ["ordered"]]],
                    }
                )

    # ----- future production/ordering tables (Order book) -----
    # The future tables contain planned production and orders. They are input data
    # for the next period, so we record them as inputs here.

    # future planned production
    prod_planned = _find_node_by_title(
        doc, f"{scope}: Order book: Orders received and production planned for days 43 to 49"
    )
    if prod_planned:
        for idx, row in table_rows(prod_planned):
            product = row.get("product")
            prod_val = row.get("planned production")
            try:
                prod_int = int(prod_val)
            except Exception:
                prod_int = None
            if product and prod_int is not None:
                inputs_list.append(
                    {
                        "id": f"{product}_future_production_{row.get('day')}",
                        "time": float(row.get("day", "")),  # future day
                        "kind": "future_production",
                        "entities": [product],
                        "fields": {"produced": prod_int},
                        "src": [[prod_planned["node_id"], idx, ["planned production"]]],
                    }
                )

    # future orders
    orders_future = _find_node_by_title(
        doc,
        f"{scope}: Order book: Orders received and production planned for days 43 to 49",
    )
    if orders_future:
        for idx, row in table_rows(orders_future):
            product = row.get("product")
            order_val = row.get("ordered")
            try:
                order_int = int(order_val)
            except Exception:
                order_int = None
            if product and order_int is not None:
                inputs_list.append(
                    {
                        "id": f"{product}_future_order_{row.get('day')}",
                        "time": float(row.get("day", "")),
                        "kind": "future_order",
                        "entities": [product],
                        "fields": {"ordered": order_int},
                        "src": [[orders_future["node_id"], idx, ["ordered"]]],
                    }
                )
    return inputs_list


def outcomes(doc: Dict, scope: str) -> List[Dict[str, Any]]:
    """
    Everything the process produces: shipped, backordered, stock per day,
    and the explicit events recorded in the Events list.
    """
    outcome_list = []

    ledger_node = _find_node_by_title(doc, f"{scope}: Daily ledger")
    if ledger_node:
        for idx, row in table_rows(ledger_node):
            product = row.get("product")
            # Shipped, backordered, stock yield outcomes for each product
            day_float = float(row.get("day", ""))
            # Build entities list once
            entities = [product] if product else []
            # shipped
            try:
                shipped_val = int(row.get("shipped", ""))
            except Exception:
                shipped_val = None
            outcome_list.append(
                {
                    "time": day_float,
                    "kind": "shipped",
                    "entities": entities,
                    "value": shipped_val,
                    "src": [[ledger_node["node_id"], idx, ["shipped"]]],
                }
            )
            # backordered
            try:
                back_val = int(row.get("backordered", ""))
            except Exception:
                back_val = None
            outcome_list.append(
                {
                    "time": day_float,
                    "kind": "backordered",
                    "entities": entities,
                    "value": back_val,
                    "src": [[ledger_node["node_id"], idx, ["backordered"]]],
                }
            )
            # stock
            try:
                stock_val = int(row.get("stock", ""))
            except Exception:
                stock_val = None
            outcome_list.append(
                {
                    "time": day_float,
                    "kind": "stock",
                    "entities": entities,
                    "value": stock_val,
                    "src": [[ledger_node["node_id"], idx, ["stock"]]],
                }
            )

    # events from the Events list
    events_node = _find_node_by_title(doc, f"{scope}: Events")
    if events_node:
        if events_node.get("kind") == "list":
            lines = events_node.get("lines", [])
            outcome_list.extend(_parse_events(lines, events_node["node_id"]))
        elif events_node.get("kind") == "text":
            # No events recorded
            pass

    return outcome_list


def params(doc: Dict, scope: str) -> Dict[str, Union[int, float]]:
    """
    Constant values that appear in the document.

    For this domain we return the daily dispatch capacity specified in the scope text,
    rounded to the nearest 50 kg as per the description.
    """
    params_dict = {}
    scope_node = _find_node_by_title(doc, scope)
    if not scope_node:
        return params_dict

    # The scope text node contains the capacity in its first line
    if scope_node.get("kind") == "text":
        txt = scope_node.get("text", "")
    else:
        txt = ""

    cap = _parse_capacity(txt)
    if cap is not None:
        # Round to the nearest 50 as per spec (though the capacity already is rounded)
        cap_rounded = int(round(cap / 50.0) * 50)
        params_dict["dispatch_capacity_kg"] = cap_rounded

    # Add product weight per unit as a parameter (optional, but useful)
    prod_node = _find_node_by_title(doc, f"{scope}: Products")
    if prod_node:
        for _, row in table_rows(prod_node):
            product = row.get("product")
            weight_str = row.get("kg per unit")
            try:
                weight = float(weight_str)
            except Exception:
                continue
            params_dict[f"weight_{product}_kg"] = weight

    return params_dict

