    for n in doc.get("nodes", []):
        if n.get("title") == title:
            return n
    return None


def _find_nodes_by_title_prefix(doc: Dict, prefix: str) -> List[Dict]:
    """Return all nodes whose title starts with *prefix*."""
    return [n for n in doc.get("nodes", []) if n.get("title", "").startswith(prefix)]


def _parse_int(val: str) -> Union[int, None]:
