def entities(doc: Dict, scope: str) -> List[Dict[str, str]]:
    """
    Every distinct entity the scope's records are about.
    The only entities are the product codes in the Products table.
    Each entity dictionary contains its id and a human‑readable description.
    """
    prod = _find_node_by_title(doc, f"{scope}: Products")
    if not prod:
        return []

    ent_list: List[Dict[str, str]] = []
    for _, row in table_rows(prod):
        pid = row.get("product")
        if pid:
            ent_list.append({"id": pid, "description": pid})
    return ent_list


def recorded_end(doc: Dict, scope: str) -> Union[float, None]:
    """
    The last time point covered by the scope's records.
    For this document it is the maximum day number in the Daily ledger table.
    """
    ledger = _find_node_by_title(doc, f"{scope}: Daily ledger")
    if not ledger:
        return None

    max_day: Union[float, None] = None
    for _, row in table_rows(ledger):
        d = _parse_float(row.get("day", ""))
        if d is not None:
            if max_day is None or d > max_day:
                max_day = d
    return max_day


def inputs(doc: Dict, scope: str) -> List[Dict[str, Any]]:
    """
    All records that are external inputs to the process:
    - opening stock at the start of the period
    - daily production
    - daily customer orders
    - future production and orders from the order book
    """
    inps: List[Dict[str, Any]] = []

    # Opening stock ------------------------------------------------------
    prod_node = _find_node_by_title(doc, f"{scope}: Products")
    if prod_node:
        for row_index, row in table_rows(prod_node):
            pid = row.get("product")
            opening = _parse_int(row.get("opening stock", ""))
            if pid and opening is not None:
                inps.append(
                    {
                        "id": f"{pid}_open",
                        "time": None,
                        "kind": "opening_stock",
                        "entities": [pid],
                        "fields": {"stock": opening},
                        "src": [[prod_node["node_id"], row_index, ["opening stock"]]],
                    }
                )

    # Daily production and orders -----------------------------------------
    ledger_node = _find_node_by_title(doc, f"{scope}: Daily ledger")
    if ledger_node:
        for row_index, row in table_rows(ledger_node):
            pid = row.get("product")
            day = _parse_float(row.get("day", ""))
            if not (pid and day is not None):
                continue

            # production
            prod_val = _parse_int(row.get("produced", ""))
            if prod_val is not None:
                inps.append(
                    {
                        "id": f"{pid}_prod_{int(day)}",
                        "time": day,
                        "kind": "production",
                        "entities": [pid],
                        "fields": {"produced": prod_val},
                        "src": _src(ledger_node["node_id"], row_index, ["produced"]),
                    }
                )

            # orders
            ord_val = _parse_int(row.get("ordered", ""))
            if ord_val is not None and ord_val > 0:
                inps.append(
                    {
                        "id": f"{pid}_ord_{int(day)}",
                        "time": day,
                        "kind": "order_placed",
                        "entities": [pid],
                        "fields": {"ordered": ord_val},
                        "src": _src(ledger_node["node_id"], row_index, ["ordered"]),
                    }
                )

    # Future production and orders ---------------------------------------
    # Order book tables: titles contain "planned for days"
    order_book_titles = [
        n["title"] for n in doc.get("nodes", [])
        if n.get("title", "").startswith(f"{scope}: Order book: Orders received and production planned for days")
    ]
    for title in order_book_titles:
        node = node_by_title(doc, title)
        if not node or node.get("kind") != "table":
            continue
        for row_index, row in table_rows(node):
            pid = row.get("product")
            day = _parse_int(row.get("day", ""))  # day in the future
            if pid is None or day is None:
                continue
            # future production
            prod_val = _parse_int(row.get("planned production", ""))
            if prod_val is not None:
                inps.append(
                    {
                        "id": f"{pid}_future_prod_{day}",
                        "time": float(day),
                        "kind": "future_production",
                        "entities": [pid],
                        "fields": {"produced": prod_val},
                        "src": _src(node["node_id"], row_index, ["planned production"]),
                    }
                )
            # future orders
            ord_val = _parse_int(row.get("ordered", ""))
            if ord_val is not None:
                inps.append(
                    {
                        "id": f"{pid}_future_ord_{day}",
                        "time": float(day),
                        "kind": "future_order",
                        "entities": [pid],
                        "fields": {"ordered": ord_val},
                        "src": _src(node["node_id"], row_index, ["ordered"]),
                    }
                )

    return inps


def outcomes(doc: Dict, scope: str) -> List[Dict[str, Any]]:
    """
    All recorded outcomes of the process:
    - shipped, backordered, stock values from the Daily ledger
    - explicit events recorded in the Events list
    """
    outs: List[Dict[str, Any]] = []

    # From Daily ledger ---------------------------------------------------
    ledger = _find_node_by_title(doc, f"{scope}: Daily ledger")
    if ledger:
        for row_index, row in table_rows(ledger):
            pid = row.get("product")
            day = _parse_float(row.get("day", ""))
            time = day  # None if day missing
            entities = [pid] if pid else []

            # shipped
            shipped_val = _parse_int(row.get("shipped", ""))
            if shipped_val is not None:
                outs.append(
                    {
                        "time": time,
                        "kind": "shipped",
                        "entities": entities,
                        "value": shipped_val,
                        "src": _src(ledger["node_id"], row_index, ["day", "product", "shipped"]),
                    }
                )

            # backordered
            back_val = _parse_int(row.get("backordered", ""))
            if back_val is not None:
                outs.append(
                    {
                        "time": time,
                        "kind": "backordered",
                        "entities": entities,
                        "value": back_val,
                        "src": _src(ledger["node_id"], row_index, ["day", "product", "backordered"]),
                    }
                )

            # stock
            stock_val = _parse_int(row.get("stock", ""))
            if stock_val is not None:
                outs.append(
                    {
                        "time": time,
                        "kind": "stock",
                        "entities": entities,
                        "value": stock_val,
                        "src": _src(ledger["node_id"], row_index, ["day", "product", "stock"]),
                    }
                )

    # From Events list ---------------------------------------------------------
    events_node = _find_node_by_title(doc, f"{scope}: Events")
    if events_node and events_node.get("kind") == "list":
        lines = events_node.get("lines", [])
        for line_index, line in enumerate(lines):
            # runs out of stock
            m = re.search(r"Day\s+(\d+).*runs out of stock.*\((\d+)\s*units backordered\)", line, re.I)
            if m:
                day = float(m.group(1))
                units = int(m.group(2))
                outs.append(
                    {
                        "time": day,
                        "kind": "runs_out_of_stock",
                        "entities": [],  # entity id is hard to parse from generic line
                        "value": units,
                        "src": [[events_node["node_id"], line_index]],
                    }
                )
                continue
            # capacity reached
            m = re.search(r"Day\s+(\d+).*capacity reached", line, re.I)
            if m:
                day = float(m.group(1))
                outs.append(
                    {
                        "time": day,
                        "kind": "capacity_reached",
                        "entities": [],
                        "value": None,
                        "src": [[events_node["node_id"], line_index]],
                    }
                )
                continue
            # order fully backordered
            m = re.search(r"order for ([A-Za-z0-9\-]+) placed on day \d+ fully backordered.*\((\d+)\s*units, none shipped\)", line, re.I)
            if m:
                pid = m.group(1)
                units = int(m.group(2))
                outs.append(
                    {
                        "time": _parse_float(line.split()[1](0) if False else 0),  # placeholder, can't reliably get day
                        "kind": "order_fully_backordered",
                        "entities": [pid],
                        "value": units,
                        "src": [[events_node["node_id"], line_index]],
                    }
                )
                continue
            # backlog cleared
            m = re.search(r"backlog cleared for ([A-Za-z0-9\-]+)", line, re.I)
            if m:
                pid = m.group(1)
                outs.append(
                    {
                        "time": _parse_float(line.split()[1](0) if False else 0),  # placeholder
                        "kind": "backlog_cleared",
                        "entities": [pid],
                        "value": None,
                        "src": [[events_node["node_id"], line_index]],
                    }
                )
                continue
    return outs


def params(doc: Dict, scope: str) -> Dict[str, Union[int, float]]:
    """
    Constant parameters explicitly stated in the document:
     * daily dispatch capacity (rounded to nearest 50kg)
     * product weight per unit
    """
    params: Dict[str, Union[int, float]] = {}

    # Capacity -----------------------------------------------------------
    scope_node = _find_node_by_title(doc, scope)
    if scope_node and scope_node.get("kind") == "text":
        txt = scope_node.get("text", "")
        m = re.search(r"Daily dispatch capacity:\s+([\d,]+)\s+kg", txt)
        if m:
            cap_val = int(m.group(1).replace(",", ""))
            # Round to nearest 50 kg as required
            cap_rounded = int(round(cap_val / 50.0) * 50)
            params["dispatch_capacity_kg"] = cap_rounded

    # Product weights -----------------------------------------------------
    prod_node = _find_node_by_title(doc, f"{scope}: Products")
    if prod_node:
        for _, row in table_rows(prod_node):
            pid = row.get("product")
            kg = row.get("kg per unit")
            if pid and kg:
                try:
                    weight = float(kg)
                    params[f"weight_{pid}_kg"] = weight
                except Exception:
                    pass

    return params

